type fieldError struct {
	Field   string `json:"field"`
	Message string `json:"message"`
}

type apiError struct {
	Code    string       `json:"code"`
	Message string       `json:"message"`
	Details []fieldError `json:"details,omitempty"`
}

err := apiError{
	Code:    "INVALID_ARGUMENT",
	Message: "参数校验失败",
	Details: []fieldError{{Field: "email", Message: "格式不合法"}},
}
body, _ := json.Marshal(err)
fmt.Println(string(body))

type cursor struct {
	CreatedAt time.Time `json:"created_at"`
	ID        int64     `json:"id"`
}

raw, _ := json.Marshal(cursor{CreatedAt: time.Now().UTC(), ID: 42})
fmt.Printf("%x\n", raw)

type record struct {
	Body      []byte
	CreatedAt time.Time
}

seen := map[string]record{}
key := "idem-20261029-001"
if r, ok := seen[key]; ok {
	fmt.Println("重放上次结果:", string(r.Body))
} else {
	resp := []byte(`{"order_id":1001}`)
	seen[key] = record{Body: resp, CreatedAt: time.Now()}
	fmt.Println("首次执行:", string(resp))
}
